sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    if (current.approval_status != 'approved') return;
    if (current.vin.nil()) return;

    var invGR = current.vin.getRefRecord();
    if (!invGR.isValidRecord()) return;

    // Transaction ka field (jo naam valid mile wahi use hoga) -> Inventory ka column
    var pairs = [
        { src: ['to_dealer'],   inv: 'dealer_name' },
        { src: ['to_customer', 'customer_to', 'to_customer_name', 'new_customer'], inv: 'customer_name' }
    ];

    var changed = false;

    for (var i = 0; i < pairs.length; i++) {
        var p = pairs[i];

        // Sahi source field dhundo
        var srcField = '';
        for (var j = 0; j < p.src.length; j++) {
            if (current.isValidField(p.src[j])) { srcField = p.src[j]; break; }
        }
        if (srcField == '') {
            gs.error('ITH inventory update: transaction mein field nahi mila -> ' + p.src.join(' / '));
            continue;
        }

        // Is transaction mein ye field bhara hi nahi, to chhod do
        if (current.getElement(srcField).nil()) continue;

        if (!invGR.isValidField(p.inv)) {
            gs.error('ITH inventory update: inventory mein field nahi mila -> ' + p.inv);
            continue;
        }

        // Dono reference ek hi table ko point karne chahiye
        var srcRef = String(current.getElement(srcField).getReferenceTable());
        var invRef = String(invGR.getElement(p.inv).getReferenceTable());
        if (srcRef != invRef) {
            gs.error('ITH inventory update: reference table alag hai -> ' + srcField + ': ' + srcRef + ' | ' + p.inv + ': ' + invRef);
            continue;
        }

        invGR.setValue(p.inv, current.getValue(srcField));
        changed = true;
        gs.info('ITH inventory update: ' + p.inv + ' = ' + current.getElement(srcField).getDisplayValue() + ' | VIN ' + current.vin.getDisplayValue());
    }

    if (changed) invGR.update();

})(current, previous);
